    if (state.mode === "rescue") return paintRescue();
    $("supply").hidden = true;
    if (state.mode === "sim") return paintSim();
    if (state.mode === "base") return paintBase();
    if (state.mode === "eva") return paintEva();
    const i = state.mode === "here" ? state.here : state.sel;
    const v = $("pt-verdict");
    showPov(i);
    if (i < 0) {
      $("pt-where").textContent = "지도를 눌러 현재 위치를 찍으세요";
      v.className = "verdict"; v.textContent = "";
      $("pt-meters").innerHTML = ""; $("pt-facts").innerHTML = ""; drawVec({ path: null }); return;
    }
    const S = setNow();
    $("pt-where").textContent = where(i);
    if (!(FLAGS[i] & 1)) {
      v.className = "verdict bad"; v.textContent = "지형 자료 없음";
      $("pt-meters").innerHTML = ""; $("pt-facts").innerHTML = "<dt>이 칸</dt><dd>HiRISE 지형 자료가 없는 칸입니다</dd>";
      drawVec({ path: null }); return;
    }
