    const F = SIM.frames, i0 = Math.max(0, Math.min(F.length - 1, Math.floor(fi))), i1 = Math.min(F.length - 1, i0 + 1), u = Math.max(0, Math.min(1, fi - i0));
    const a = F[i0].pos, b = F[i1].pos;
    const x = ((a % W) + 0.5) * (1 - u) + ((b % W) + 0.5) * u, y = (((a / W) | 0) + 0.5) * (1 - u) + (((b / W) | 0) + 0.5) * u;
    el.style.left = `${x / W * 100}%`; el.style.top = `${y / R * 100}%`;
